func waitingRoomValidateConfiguredBypassRules(ctx context.Context, wrapper types.Object) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if wrapper.IsNull() || wrapper.IsUnknown() {
		return diagnostics
	}
	var value waitingRoomWrapperModel
	diagnostics.Append(wrapper.As(ctx, &value, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() || value.Items.IsNull() || value.Items.IsUnknown() {
		return diagnostics
	}
	if len(value.Items.Elements()) > waitingRoomBypassRulesMaxItems {
		diagnostics.AddError("Invalid waiting room bypass_rules", fmt.Sprintf("bypass_rules may contain at most %d item blocks.", waitingRoomBypassRulesMaxItems))
		return diagnostics
	}
	var items []waitingRoomBypassRulesItemModel
	diagnostics.Append(value.Items.ElementsAs(ctx, &items, false)...)
	if diagnostics.HasError() {
		return diagnostics
	}
	for index, item := range items {
		location := fmt.Sprintf("bypass_rules item %d", index+1)
		if item.RuleType.IsNull() {
			diagnostics.AddError("Invalid waiting room item", location+" rule_type is required.")
		} else if !item.RuleType.IsUnknown() {
			waitingRoomValidateString(location, " rule_type", item.RuleType.ValueString(), 0, 64, &diagnostics)
			waitingRoomValidatePattern(location, " rule_type", item.RuleType.ValueString(), waitingRoomBypassRulesRuleTypePattern, "must match source-ip", &diagnostics)
			if !waitingRoomBypassRulesRuleTypeValid(item.RuleType.ValueString()) {
				diagnostics.AddError("Invalid waiting room item", location+" rule_type must be one of source-ip.")
			}
		}
		if item.RuleValue.IsNull() {
			diagnostics.AddError("Invalid waiting room item", location+" rule_value is required.")
		} else if !item.RuleValue.IsUnknown() {
			waitingRoomValidateString(location, " rule_value", item.RuleValue.ValueString(), 0, 0, &diagnostics)
		}
	}
	return diagnostics
}

func waitingRoomBuildConfiguredBypassRules(ctx context.Context, configured, planned types.Object, diagnostics diag.Diagnostics) (waitingRoomBypassRulesOwnedList, diag.Diagnostics) {
	if configured.IsNull() {
		return waitingRoomBypassRulesOwnedList{}, diagnostics
	}
	if configured.IsUnknown() {
		diagnostics.AddError("Unknown waiting room bypass_rules", "The bypass_rules ownership wrapper must be known during apply.")
		return waitingRoomBypassRulesOwnedList{}, diagnostics
	}
	if planned.IsNull() || planned.IsUnknown() {
		diagnostics.AddError("Unknown waiting room bypass_rules", "The planned bypass_rules ownership wrapper must be known during apply.")
		return waitingRoomBypassRulesOwnedList{}, diagnostics
	}
	var configWrapper, planWrapper waitingRoomWrapperModel
	diagnostics.Append(configured.As(ctx, &configWrapper, basetypes.ObjectAsOptions{})...)
	diagnostics.Append(planned.As(ctx, &planWrapper, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() {
		return waitingRoomBypassRulesOwnedList{}, diagnostics
	}
	if configWrapper.Items.IsUnknown() || planWrapper.Items.IsUnknown() {
		diagnostics.AddError("Unknown waiting room bypass_rules", "The bypass_rules item blocks must be known during apply.")
		return waitingRoomBypassRulesOwnedList{}, diagnostics
	}
	if configWrapper.Items.IsNull() {
		return waitingRoomBypassRulesOwnedList{Set: true, Items: []waitingRoomBypassRulesWireItem{}}, diagnostics
	}

	var configItems, planItems []waitingRoomBypassRulesItemModel
	diagnostics.Append(configWrapper.Items.ElementsAs(ctx, &configItems, false)...)
	if planWrapper.Items.IsNull() {
		if len(configItems) != 0 {
			diagnostics.AddError("Invalid waiting room bypass_rules", "The planned item list unexpectedly became null.")
		}
		return waitingRoomBypassRulesOwnedList{Set: true, Items: []waitingRoomBypassRulesWireItem{}}, diagnostics
	}
	diagnostics.Append(planWrapper.Items.ElementsAs(ctx, &planItems, false)...)
	if diagnostics.HasError() {
		return waitingRoomBypassRulesOwnedList{}, diagnostics
	}
	if len(configItems) != len(planItems) {
		diagnostics.AddError("Invalid waiting room bypass_rules", "Configured and planned item counts differ.")
		return waitingRoomBypassRulesOwnedList{}, diagnostics
	}
	if len(configItems) > waitingRoomBypassRulesMaxItems {
		diagnostics.AddError("Invalid waiting room bypass_rules", fmt.Sprintf("bypass_rules may contain at most %d item blocks.", waitingRoomBypassRulesMaxItems))
		return waitingRoomBypassRulesOwnedList{}, diagnostics
	}

	items := make([]waitingRoomBypassRulesWireItem, 0, len(configItems))
	for index := range configItems {
		configuredItem := configItems[index]
		plannedItem := planItems[index]
		location := fmt.Sprintf("bypass_rules item %d", index+1)
		item := waitingRoomBypassRulesWireItem{
			Index: index + 1,
		}
		rule_typeValue, ok := waitingRoomPlannedRequiredString(configuredItem.RuleType, plannedItem.RuleType, location+" rule_type", &diagnostics)
		if !ok {
			continue
		}
		waitingRoomValidateString(location, " rule_type", rule_typeValue, 0, 64, &diagnostics)
		waitingRoomValidatePattern(location, " rule_type", rule_typeValue, waitingRoomBypassRulesRuleTypePattern, "must match source-ip", &diagnostics)
		if !waitingRoomBypassRulesRuleTypeValid(rule_typeValue) {
			diagnostics.AddError("Invalid waiting room item", location+" rule_type must be one of source-ip.")
		}
		item.RuleType = rule_typeValue
		rule_valueValue, ok := waitingRoomPlannedRequiredString(configuredItem.RuleValue, plannedItem.RuleValue, location+" rule_value", &diagnostics)
		if !ok {
			continue
		}
		waitingRoomValidateString(location, " rule_value", rule_valueValue, 0, 0, &diagnostics)
		item.RuleValue = rule_valueValue
		items = append(items, item)
	}
	return waitingRoomBypassRulesOwnedList{Set: true, Items: items}, diagnostics
}
