func waitingRoomDecodeBypassRules(raw json.RawMessage) (waitingRoomBypassRulesOwnedList, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if len(raw) == 0 {
		return waitingRoomBypassRulesOwnedList{}, diagnostics
	}
	if waitingRoomJSONNull(raw) {
		diagnostics.AddError("Malformed waiting room result", "The successful API result contained null bypass_rules instead of an array.")
		return waitingRoomBypassRulesOwnedList{}, diagnostics
	}
	var rawItems []json.RawMessage
	if err := json.Unmarshal(raw, &rawItems); err != nil {
		diagnostics.AddError("Malformed waiting room result", "The successful API result contained a non-array bypass_rules value.")
		return waitingRoomBypassRulesOwnedList{}, diagnostics
	}
	if len(rawItems) > waitingRoomBypassRulesMaxItems {
		diagnostics.AddError("Malformed waiting room result", fmt.Sprintf("The successful API result contained more than %d bypass_rules items.", waitingRoomBypassRulesMaxItems))
		return waitingRoomBypassRulesOwnedList{}, diagnostics
	}

	items := make([]waitingRoomBypassRulesWireItem, 0, len(rawItems))
	seen := make(map[int]struct{}, len(rawItems))
	knownKeys := map[string]struct{}{
		"idx":        {},
		"rule_type":  {},
		"rule_value": {},
	}
	for position, rawItem := range rawItems {
		location := fmt.Sprintf("bypass_rules item %d", position+1)
		var object map[string]json.RawMessage
		if err := json.Unmarshal(rawItem, &object); err != nil || object == nil {
			diagnostics.AddError("Malformed waiting room result", location+" was not an object.")
			continue
		}
		unknown := make([]string, 0)
		for key := range object {
			if _, ok := knownKeys[key]; !ok {
				unknown = append(unknown, key)
			}
		}
		sort.Strings(unknown)
		if len(unknown) != 0 {
			diagnostics.AddError("Unknown waiting room item field", location+" contained unsupported keys: "+strings.Join(unknown, ", ")+".")
			continue
		}
		index, ok := waitingRoomDecodeIndex(object["idx"], location, "int", &diagnostics)
		if !ok {
			continue
		}
		if _, duplicate := seen[index]; duplicate {
			diagnostics.AddError("Malformed waiting room result", fmt.Sprintf("%s used duplicate idx %d.", location, index))
			continue
		}
		seen[index] = struct{}{}
		item := waitingRoomBypassRulesWireItem{Index: index}
		rule_typeValue, ok := waitingRoomDecodeRequiredString(object["rule_type"], location+" rule_type", &diagnostics)
		if !ok {
			continue
		}
		waitingRoomValidateString(location, " rule_type", rule_typeValue, 0, 64, &diagnostics)
		waitingRoomValidatePattern(location, " rule_type", rule_typeValue, waitingRoomBypassRulesRuleTypePattern, "must match source-ip", &diagnostics)
		if !waitingRoomBypassRulesRuleTypeValid(rule_typeValue) {
			diagnostics.AddError("Malformed waiting room result", location+" rule_type was not one of source-ip.")
		}
		item.RuleType = rule_typeValue
		rule_valueValue, ok := waitingRoomDecodeRequiredString(object["rule_value"], location+" rule_value", &diagnostics)
		if !ok {
			continue
		}
		waitingRoomValidateString(location, " rule_value", rule_valueValue, 0, 0, &diagnostics)
		item.RuleValue = rule_valueValue
		items = append(items, item)
	}
	if diagnostics.HasError() {
		return waitingRoomBypassRulesOwnedList{}, diagnostics
	}
	sort.Slice(items, func(i, j int) bool { return items[i].Index < items[j].Index })
	return waitingRoomBypassRulesOwnedList{Set: true, Items: items}, diagnostics
}

func waitingRoomBypassRulesWrapperValue(owned waitingRoomBypassRulesOwnedList, subItemOwnedMasks map[string][]bool) (types.Object, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if !owned.Set {
		return types.ObjectNull(waitingRoomBypassRulesWrapperAttributeTypes), diagnostics
	}
	elements := make([]attr.Value, 0, len(owned.Items))
	for _, item := range owned.Items {
		objectValues := map[string]attr.Value{}
		objectValues["rule_type"] = types.StringValue(item.RuleType)
		objectValues["rule_value"] = types.StringValue(item.RuleValue)
		object, objectDiagnostics := types.ObjectValue(waitingRoomBypassRulesItemAttributeTypes, objectValues)
		diagnostics.Append(objectDiagnostics...)
		elements = append(elements, object)
	}
	list, listDiagnostics := types.ListValue(types.ObjectType{AttrTypes: waitingRoomBypassRulesItemAttributeTypes}, elements)
	diagnostics.Append(listDiagnostics...)
	wrapper, wrapperDiagnostics := types.ObjectValue(waitingRoomBypassRulesWrapperAttributeTypes, map[string]attr.Value{"item": list})
	diagnostics.Append(wrapperDiagnostics...)
	return wrapper, diagnostics
}
func waitingRoomDecodeIndex(raw json.RawMessage, location string, idxKind string, diagnostics *diag.Diagnostics) (int, bool) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || waitingRoomJSONNull(trimmed) {
		diagnostics.AddError("Malformed waiting room result", location+" did not contain a non-null integer idx.")
		return 0, false
	}
	if trimmed[0] != '-' && (trimmed[0] < '0' || trimmed[0] > '9') {
		diagnostics.AddError("Malformed waiting room result", location+" contained a non-integer idx.")
		return 0, false
	}
	var number json.Number
	if err := json.Unmarshal(trimmed, &number); err != nil {
		diagnostics.AddError("Malformed waiting room result", location+" contained a non-integer idx.")
		return 0, false
	}
	value64, err := number.Int64()
	if err != nil || value64 <= 0 || int64(int(value64)) != value64 {
		diagnostics.AddError("Malformed waiting room result", location+" contained an idx that was not a positive integer.")
		return 0, false
	}
	return int(value64), true
}
