// DecodeOptionalStringWithDefault decodes an optional string item field,
// substituting the reviewed default when the successful GET omits the key or
// returns null. This mirrors the encode path (which sends the reviewed default
// when the practitioner omits the field), so the refreshed state carries the
// reviewed default rather than null and a configured-default value does not
// perpetual-diff when the backend omits default-valued keys.
func waitingRoomDecodeOptionalStringWithDefault(object map[string]json.RawMessage, key, location string, maximum int, defaultValue string, diagnostics *diag.Diagnostics) *string {
	raw, ok := object[key]
	if !ok || waitingRoomJSONNull(raw) {
		d := defaultValue
		return &d
	}
	var value string
	if err := json.Unmarshal(raw, &value); err != nil {
		diagnostics.AddError("Malformed waiting room result", location+" "+key+" was not a string or null.")
		return nil
	}
	if maximum > 0 && utf8.RuneCountInString(value) > maximum {
		diagnostics.AddError("Malformed waiting room result", fmt.Sprintf("%s %s exceeded %d UTF-8 characters.", location, key, maximum))
		return nil
	}
	return &value
}
