// waitingRoomDecodeBoolWithDefault decodes an optional boolean item
// field that carries a reviewed provider default. A missing key (omission) or
// an accepted null decodes to the reviewed default (distinct from a required
// field, which rejects a missing key). A present non-boolean value is rejected.
func waitingRoomDecodeBoolWithDefault(object map[string]json.RawMessage, key, location string, defaultValue bool, diagnostics *diag.Diagnostics) bool {
	raw, ok := object[key]
	if !ok || waitingRoomJSONNull(raw) {
		return defaultValue
	}
	var value bool
	if err := json.Unmarshal(raw, &value); err != nil {
		diagnostics.AddError("Malformed waiting room result", location+" "+key+" was not a boolean or null.")
		return defaultValue
	}
	return value
}

func waitingRoomOwnership(ctx context.Context, template bool, ownership wafmodule.OwnershipContext) (waitingRoomOwnershipSet, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if template {
		return waitingRoomOwnershipSet{BypassRules: false}, diagnostics
	}
	if ownership.Source == wafmodule.OwnershipImported {
		return waitingRoomOwnershipSet{BypassRules: true}, diagnostics
	}
	configsValue, ownershipDiagnostics := wafmodule.OwnershipConfigs(ctx, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() || configsValue.IsNull() {
		return waitingRoomOwnershipSet{BypassRules: false}, diagnostics
	}
	if configsValue.IsUnknown() {
		diagnostics.AddError("Unknown waiting room ownership", "The configs ownership state was unknown while flattening.")
		return waitingRoomOwnershipSet{BypassRules: false}, diagnostics
	}
	var configs waitingRoomConfigsModel
	diagnostics.Append(configsValue.As(ctx, &configs, basetypes.ObjectAsOptions{})...)
	return waitingRoomOwnershipSet{BypassRules: !configs.BypassRules.IsNull()}, diagnostics
}
func waitingRoomValidateString(location, label, value string, minimum, maximum int, diagnostics *diag.Diagnostics) {
	if minimum > 0 && utf8.RuneCountInString(value) < minimum {
		diagnostics.AddError("Invalid waiting room item", fmt.Sprintf("%s%s must be at least %d UTF-8 characters.", location, label, minimum))
	}
	if maximum > 0 && utf8.RuneCountInString(value) > maximum {
		diagnostics.AddError("Invalid waiting room item", fmt.Sprintf("%s%s exceeds %d UTF-8 characters.", location, label, maximum))
	}
}
func waitingRoomValidatePattern(location, label, value string, pattern *regexp.Regexp, message string, diagnostics *diag.Diagnostics) {
	if !pattern.MatchString(value) {
		diagnostics.AddError("Invalid waiting room item", fmt.Sprintf("%s%s %s.", location, label, message))
	}
}

func waitingRoomBypassRulesRuleTypeValid(value string) bool {
	_, ok := waitingRoomBypassRulesRuleTypeValues[value]
	return ok
}

func waitingRoomJSONNull(raw json.RawMessage) bool {
	return bytes.Equal(bytes.TrimSpace(raw), []byte("null"))
}

// RejectItemNullUnlessNullable reports a malformed-result diagnostic when a
// collection-item field is present in the remote response as an explicit JSON
// null but the pinned schema does not mark the field nullable. A missing key
// is not rejected here (optional omission is handled by the decode helpers).
func waitingRoomRejectItemNullUnlessNullable(object map[string]json.RawMessage, key string, allowNull bool, location string, diagnostics *diag.Diagnostics) {
	raw, ok := object[key]
	if !ok {
		return
	}
	if waitingRoomJSONNull(raw) && !allowNull {
		diagnostics.AddError("Malformed waiting room result", location+" "+key+" was null, which the pinned schema does not mark nullable.")
	}
}
